class CustomInsertImage extends Plugin {
    init() {
        const editor = this.editor;
        editor.commands.add('customInsertImage', new CustomInsertImageCommand(editor));
        editor.ui.componentFactory.add('customInsertImage', locale => {
            const command = editor.commands.get('customInsertImage');
            const view = new ButtonView(locale);
            view.set({
                label: 'Pictures',
                icon: imageIcon,
                tooltip: true,
            });

            view.bind('isEnabled').to(command);
            view.bind('isOn').to(command, 'value', value => value === '');

            this.listenTo(view, 'execute', () => {
                const ishere = true;
                editor.execute('customInsertImage', {});
                editor.editing.view.focus();
            });
            return view;
        });
    }

}

