class CustomSave extends Plugin {
    init() {
        const editor = this.editor;
        editor.commands.add('customSave', new CustomSaveCommand(editor));
        editor.ui.componentFactory.add('customSave', locale => {
            const command = editor.commands.get('customSave');
            const view = new ButtonView(locale);
            view.set({
                label: 'Save',
                icon: saveIcon,
                tooltip: true,
                keystroke: 'Ctrl + S',
            });
            // view.on( 'execute', () => {

            // } );
            view.bind('isEnabled').to(command);
            view.bind('isOn').to(command, 'value', value => value === '');
            this.listenTo(view, 'execute', () => {
                editor.execute('customSave', {});
                editor.editing.view.focus();
            });
            editor.keystrokes.set('Ctrl + S', (keyEvtData, cancel) => {
                editor.execute('customSave', {});
                editor.editing.view.focus();
                cancel();
            });
            return view;
        });
    }
}
